package main
import("context";"encoding/json";"net/http";"net/http/httptest";"os";"path/filepath";"strings";"testing";"time")
func TestSanitize(t *testing.T){for _,s:=range []string{"Authorization: Bearer ghp_ABCDEFGHIJK","Cookie: session=secretval","#code=deadbeef0123456789","user_code=ABCD-1234","github_pat_ABCDEF123456","operator code=123456789abcdef0123456789"}{o:=Sanitize(s);for _,secret:=range []string{"ghp_","secretval","deadbeef","ABCD-1234","github_pat_","123456789abcdef"}{if strings.Contains(o,secret){t.Errorf("secret leaked in %q: %q",s,o)}}}}
func TestRegistryPersistence(t *testing.T){d:=t.TempDir();a,e:=OpenOperations(d);if e!=nil{t.Fatal(e)};id:=a.SystemID();a.Event("test","before","","OK");a.Close();b,e:=OpenOperations(d);if e!=nil{t.Fatal(e)};defer b.Close();if id!=b.SystemID()||len(b.Recent(3))==0{t.Fatal("identity/log lost")};os.WriteFile(filepath.Join(d,"registry.json"),[]byte("corrupt"),0600);if _,e:=OpenOperations(d);e==nil{t.Fatal("corrupt profile not refused")}}
func TestProcessorRealHTTP(t *testing.T){s:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(map[string]string{"app":"thought-processor","protocol":"thought-processor.diagnostic/0-experimental"})}));defer s.Close();o,e:=OpenOperations(t.TempDir());if e!=nil{t.Fatal(e)};defer o.Close();target,e:=validProcessor(s.URL,7797);if e!=nil{t.Fatal(e)};o.mu.Lock();o.registry.Processor=target;o.mu.Unlock();o.CheckProcessor();if o.ProcessorState().Status!="DISCOVERED_UNVERIFIED"{t.Fatal(o.ProcessorState())};s.Close();o.CheckProcessor();if o.ProcessorState().Status!="NOT_RUNNING"{t.Fatal("offline not detected")};for _,u:=range []string{"https://127.0.0.1:44","http://10.0.0.1:55","http://127.0.0.1:7797/#code=x"}{if _,e:=validProcessor(u,7797);e==nil{t.Fatal("unsafe accepted:",u)}};_ = context.Background();_ = time.Now()}
